import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

class LibraryItem {
    private String title;
    private String itemCode;

    LibraryItem(String title, String itemCode) {
        this.title = title;
        this.itemCode = itemCode;
    }

    String getItemCode() {
        return itemCode;
    }

    double calculateFine(long daysLate) {
        return Math.max(0, daysLate) * 500.0;
    }
}

class Journal extends LibraryItem {
    Journal(String code) {
        super("Jurnal " + code, code);
    }

    @Override
    double calculateFine(long daysLate) {
        return Math.max(0, daysLate) * 300.0;
    }
}

class DigitalItem extends LibraryItem {
    DigitalItem(String code) {
        super("Digital " + code, code);
    }

    @Override
    double calculateFine(long daysLate) {
        return 0.0;
    }
}

// Buat kelas Thesis turunan LibraryItem. Constructor Thesis(String code) memanggil super("Skripsi " + code, code). Override calculateFine: Rp1000 per hari, tetapi hari yang dihitung paling banyak 20.

public class Main {
    static LibraryItem create(String type, String code) {
        switch (type) {
            case "jurnal":
                return new Journal(code);
            case "digital":
                return new DigitalItem(code);
            case "skripsi":
                return new Thesis(code);
            default:
                return new LibraryItem("Buku " + code, code);
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        List<LibraryItem> items = new ArrayList<>();
        List<Long> days = new ArrayList<>();
        while (in.hasNextLine()) {
            String line = in.nextLine().trim();
            if (line.equals("selesai")) {
                break;
            }
            String[] p = line.split(" ");
            items.add(create(p[0], p[1]));
            days.add(Long.parseLong(p[2]));
        }
        long total = 0;
        // Ulangi semua item. Untuk tiap item i cetak "<kode>: Rp<denda>" (denda dihitung lewat items.get(i).calculateFine(days.get(i)), cetak sebagai long), lalu jumlahkan ke total. Jangan periksa jenisnya dengan if.
        System.out.println("Total denda: Rp" + total);
    }
}
